Promise.all(["findings","recommendations","remediation-activities","daily-summary","collection-runs"].map(load).concat(load("secure-scores").catch(()=>[]),load("recommendation-machines").catch(()=>[]),load("subscriptions").catch(()=>[])))
  .then(([findings,recommendations,remediations,summary,runs,secureScores,recommendationMachines,subscriptions])=>{Object.assign(state,{findings,recommendations,recommendationMachines,remediations,summary,runs,secureScores,subscriptions});$("loadingNotice").hidden=true;initialize();render();})
  .catch(error=>{$("freshnessText").textContent=`Data unavailable: ${error.message}`;$("loadingNotice").classList.add("unavailable");$("loadingNotice").innerHTML=`<strong>Dashboard data unavailable</strong><span>${esc(error.message)}</span>`;$("availabilityItems").innerHTML=`<span class="header-status-item unavailable" title="Required dashboard data is unavailable"><i aria-hidden="true"></i><strong>Dashboard data</strong><span class="status-info" aria-hidden="true">i</span></span>`;});

/** Initialize for the dashboard. */
