  [...new Set(state.findings.map(row=>row.OwnerTeam).filter(Boolean))].sort().forEach(team=>$("teamFilter").insertAdjacentHTML("beforeend",`<option>${esc(team)}</option>`));
  const evidenceRows=[...state.findings,...state.recommendationMachines],inventoryIds=[...state.subscriptionInventoryById.keys()],supplementalRows=inventoryIds.length?evidenceRows.filter(row=>row.DataOrigin==="Synthetic"):evidenceRows;
  [...new Set([...inventoryIds,...supplementalRows.map(row=>row.SubscriptionId).filter(Boolean)])].sort((left,right)=>subscriptionLabel(left).localeCompare(subscriptionLabel(right))).forEach(subscription=>$("subscriptionFilter").insertAdjacentHTML("beforeend",`<option value="${esc(subscription)}">${esc(subscriptionLabel(subscription))}</option>`));
  [["severityFilter","severity"],["assetClassFilter","assetClass"],["subscriptionFilter","subscription"],["teamFilter","team"]].forEach(([id,key])=>$(id).addEventListener("change",event=>{state[key]=event.target.value;clearSelectedWorkItem();render();}));
  $("recommendationTrackingFilter").addEventListener("change",event=>{state.recommendationTrackingFilter=event.target.value;clearSelectedWorkItem();render();});
