/** Finding domain for the dashboard. */
function findingDomain(row){if(!assetClassMatches(row)||!subscriptionMatches(row))return"OutOfScope";return row.AssetClass==="AzureCloud"?"Cloud":"Devices";}
/** Recommendation kind for the dashboard. */
function recommendationKind(row){return ["securityupdate","update"].includes(String(row.RemediationType).toLowerCase())||String(row.SubCategory).toLowerCase().includes("vulnerability")?"Vulnerability":"Misconfiguration";}
/** Finding kind for the dashboard. */
function findingKind(row){const recommendation=state.recommendationsById.get(String(row.RecommendationId||""));return recommendation?recommendationKind(recommendation):"Vulnerability";}
