/** Recommendation domains for the dashboard. */
function recommendationDomains(row){const id=String(row.RecommendationId||""),machines=state.recommendationMachinesByRecommendation.get(id)||[],linked=state.findingsByRecommendation.get(id)||[];if(machines.length)return [...new Set(machines.map(findingDomain))];if(linked.length)return [...new Set(linked.map(findingDomain))];const text=`${row.Category||""} ${row.SubCategory||""}`.toLowerCase();if(text.includes("identity")||text.includes("account"))return["Identities"];if(text.includes("data"))return["Data"];if(text.includes("application"))return["SaaS Apps"];return["Devices"];}
/** Matches search for the dashboard. */
function matchesSearch(row){return !state.search||Object.values(row).some(value=>String(value??"").toLowerCase().includes(state.search));}
/** Domains match for the dashboard. */
function domainsMatch(domains){return domains.some(domain=>state.domains.has(domain));}
