function assetClassMatches(row){return state.assetClass==="All"||row.AssetClass===state.assetClass;}
/** Subscription label for the dashboard. */
function subscriptionLabel(value){const id=String(value),subscription=state.subscriptionInventoryById.get(id);if(!subscription)return id.startsWith("sample-")?id:`${id.slice(0,8)}…`;const stateLabel=subscription.State&&subscription.State!=="Enabled"?` · ${subscription.State}`:"";return `${subscription.SubscriptionName||id} · ${id}${stateLabel}`;}
/** Subscription matches for the dashboard. */
function subscriptionMatches(row){return state.subscription==="All"||(state.subscription==="NoSubscription"?!row.SubscriptionId:row.SubscriptionId===state.subscription);}
/** Return a recommendation's shared workflow state. */
function recommendationTracking(row){return state.recommendationTracking.get(String(row.RecommendationId||""))||null;}
/** Format a shared recommendation workflow state. */
function recommendationTrackingLabel(status){return{All:"All tracking states",NeedsAttention:"Needs attention",InProgress:"In progress",ReadyForValidation:"Awaiting next collection",Confirmed:"Confirmed",StillDetected:"Still detected",Untracked:"Untracked"}[status]||"Untracked";}
/** Match a recommendation against the workflow-state filter. */
function recommendationTrackingMatches(row){if(!state.recommendationTrackingEnabled||state.recommendationTrackingFilter==="All")return true;const status=recommendationTracking(row)?.effectiveStatus||"Untracked";if(state.recommendationTrackingFilter==="NeedsAttention")return!["ReadyForValidation","Confirmed"].includes(status);return status===state.recommendationTrackingFilter;}
/** Recommendation matches for the dashboard. */
function recommendationMatches(row){const id=String(row.RecommendationId||""),linked=state.findingsByRecommendation.get(id)||[],machines=state.recommendationMachinesByRecommendation.get(id)||[],classMatches=linked.some(assetClassMatches)||machines.some(assetClassMatches),subscriptionMatchesAny=linked.some(subscriptionMatches)||machines.some(subscriptionMatches);return recommendationTrackingMatches(row)&&(state.origin==="Both"||row.DataOrigin===state.origin)&&(state.severity==="All"||recommendationSeverity(row)===state.severity)&&state.recommendationTypes.has(recommendationKind(row))&&domainsMatch(recommendationDomains(row))&&(state.assetClass==="All"||classMatches)&&(state.subscription==="All"||subscriptionMatchesAny)&&(state.team==="All"||linked.some(item=>item.OwnerTeam===state.team)||machines.some(item=>item.OwnerTeam===state.team))&&(matchesSearch(row)||linked.some(matchesSearch)||machines.some(matchesSearch));}
