/** Filtered summary for the dashboard. */
function filteredSummary(){return state.summary.filter(row=>(state.origin==="Both"||row.DataOrigin===state.origin)&&(state.severity==="All"||row.Severity===state.severity)&&assetClassMatches(row)&&subscriptionMatches(row)&&state.domains.has(findingDomain(row))&&(state.team==="All"||row.OwnerTeam===state.team));}
/** Sla card items for the dashboard. */
function slaCardItems(rows){const current=rows.filter(open),fixed=rows.filter(row=>row.FindingStatus==="Fixed");return[[rows.length,"Findings found"],[fixed.length,"Defender-confirmed fixed"],[current.length,"Findings remaining"],[fixed.filter(row=>row.SlaStatus==="FixedWithinSla").length,"Policy SLA fixed within"],[fixed.filter(row=>row.SlaStatus==="FixedOutsideSla").length,"Policy SLA fixed outside"],[current.filter(row=>row.SlaStatus==="OpenOutsideSla").length,"Policy SLA open overdue"]];}
